console.log(canReachEnd([2, 4, 1, 0, 0, 3]));

solution:
function canReachEnd(jumps: number[]): boolean {
  let farthest = 0;
  for (let i = 0; i < jumps.length; i++) {
    if (i > farthest) return false;
    farthest = Math.max(farthest, i + jumps[i]);
  }
  return true;
}
